DiyTables.SubmitAfterServerV8:
/*
 * V8 Event
 * TableKey: microi_database
 * EventType: SubmitAfterServerV8
 * Version: v1.0.1
 * Function:
 * - 扩展数据库配置提交成功后递增共享缓存版本；事务回滚不发布失效通知；兼容滚动升级期间尚未提供刷新方法的旧节点。
 */

// 滚动升级期间旧节点尚无此方法，先保持历史保存行为；新节点上线后自动启用即时刷新。
if (typeof V8.Method.RefreshExtensionDatabases !== 'function') return;

// 登记提交后缓存失效；登记失败时阻止本次配置写入，避免数据库与运行缓存长期不一致。
var refreshResult = V8.Method.RefreshExtensionDatabases(V8.OsClient);
if (!refreshResult || refreshResult.Code != 1) {
  return {
    Code: 0,
    Msg: refreshResult && refreshResult.Msg
      ? refreshResult.Msg
      : '扩展数据库缓存刷新登记失败'
  };
}

DiyTables.InFormV8:
window.GetNotDiyTable = function(){
  //获取所有非DIY表
  V8.Post('/api/diytable/getNotDiyTable', {
    DataBaseId : V8.Form.Id
  }, function(result){
    if(result.Code != 1){
      V8.Tips('获取所有非DIY表失败：' + result.Msg, false);
      return;
    }
    var data = [];
    result.Data.forEach(item => {
      data.push({ TableName : item, Id : item });
    });

    V8.FieldSet('NotDiyTable', 'Data', data);
  });
}
if(V8.FormMode == 'Edit'){
  V8.FieldSet('NotDiyTable', 'Visible', true);
  V8.FieldSet('BtnLoadNotDiyTable', 'Visible', true);
  window.GetNotDiyTable();
}

